const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const q = tok[0];
let N = 1;
for (let i = 0; i < q; i++) N = Math.max(N, tok[1 + 2 * i], tok[2 + 2 * i]);
const mu = new Array(N + 1).fill(0);
mu[1] = 1;
const isComp = new Array(N + 1).fill(false), primes = [];
for (let i = 2; i <= N; i++) {
  if (!isComp[i]) { primes.push(i); mu[i] = -1; }
  for (const p of primes) {
    if (i * p > N) break;
    isComp[i * p] = true;
    if (i % p === 0) { mu[i * p] = 0; break; }
    mu[i * p] = -mu[i];
  }
}
const prefix = new Array(N + 1).fill(0);
for (let i = 1; i <= N; i++) prefix[i] = prefix[i - 1] + mu[i];
const out = [];
for (let i = 0; i < q; i++) {
  const n = tok[1 + 2 * i], m = tok[2 + 2 * i];
  let total = 0;
  const lim = Math.min(n, m);
  for (let l = 1; l <= lim; ) {
    const a = Math.floor(n / l), b = Math.floor(m / l);
    const r = Math.min(Math.floor(n / a), Math.floor(m / b));
    total += (prefix[r] - prefix[l - 1]) * a * b;
    l = r + 1;
  }
  out.push(total);
}
console.log(out.join("\n"));

