import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int q = (int) in.nval;
        int[] qn = new int[q], qm = new int[q];
        int N = 1;
        for (int i = 0; i < q; i++) {
            in.nextToken(); qn[i] = (int) in.nval;
            in.nextToken(); qm[i] = (int) in.nval;
            N = Math.max(N, Math.max(qn[i], qm[i]));
        }
        int[] mu = new int[N + 1];
        mu[1] = 1;
        boolean[] isComp = new boolean[N + 1];
        int[] primes = new int[N + 1];
        int cnt = 0;
        for (int i = 2; i <= N; i++) {
            if (!isComp[i]) { primes[cnt++] = i; mu[i] = -1; }
            for (int j = 0; j < cnt; j++) {
                int p = primes[j];
                if ((long) i * p > N) break;
                isComp[i * p] = true;
                if (i % p == 0) { mu[i * p] = 0; break; }
                mu[i * p] = -mu[i];
            }
        }
        long[] prefix = new long[N + 1];
        for (int i = 1; i <= N; i++) prefix[i] = prefix[i - 1] + mu[i];
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int n = qn[i], m = qm[i];
            long total = 0;
            int lim = Math.min(n, m);
            for (int l = 1; l <= lim; ) {
                int a = n / l, b = m / l;
                int r = Math.min(n / a, m / b);
                total += (prefix[r] - prefix[l - 1]) * (long) a * b;
                l = r + 1;
            }
            out.append(total).append('\n');
        }
        System.out.print(out);
    }
}

