#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main() {
    int q;
    scanf("%d", &q);
    vector<int> qn(q), qm(q);
    int N = 1;
    for (int i = 0; i < q; i++) {
        scanf("%d %d", &qn[i], &qm[i]);
        N = max(N, max(qn[i], qm[i]));
    }
    vector<int> mu(N + 1, 0), primes;
    vector<bool> is_comp(N + 1, false);
    mu[1] = 1;
    for (int i = 2; i <= N; i++) {
        if (!is_comp[i]) { primes.push_back(i); mu[i] = -1; }
        for (int p : primes) {
            if ((ll)i * p > N) break;
            is_comp[i * p] = true;
            if (i % p == 0) { mu[i * p] = 0; break; }
            mu[i * p] = -mu[i];
        }
    }
    vector<ll> prefix(N + 1, 0);
    for (int i = 1; i <= N; i++) prefix[i] = prefix[i - 1] + mu[i];
    for (int i = 0; i < q; i++) {
        int n = qn[i], m = qm[i];
        ll total = 0;
        int lim = min(n, m);
        for (int l = 1; l <= lim;) {
            int a = n / l, b = m / l;
            int r = min(n / a, m / b);
            total += (prefix[r] - prefix[l - 1]) * a * b;
            l = r + 1;
        }
        printf("%lld\n", total);
    }
    return 0;
}
